#include "yuzu/game_companion_catalog.h"

#include <array>

namespace GameCompanion {
namespace {

#define WIKI "https://axiom-verge.fandom.com/wiki/"

// Axiom Verge (2015). Written for Kaichii from the Axiom Verge Wiki on Fandom, which covers both
// games: only pages about the first game, or the first game's half of shared pages, are used here.
// Names of places, weapons and tools stay in English, as the game shows them.
constexpr std::array Entries{
    // Areas
    Entry{"eribu", Kind::Place, {"Eribu", "Eribu"},
          {"The rebirth labs where Trace wakes: the first area, full of secrets for later.",
           "Los laboratorios de renacimiento donde despierta Trace: la primera zona, llena de secretos para más tarde."},
          {"Test tubes of pulsing organic matter fill these caves: this is where Sudra's people rebuilt their bodies. Trace finds the Axiom Disruptor in the room next to his Rebirth Chamber, then the Nova, and fights Xedur, which rewards the Laser Drill. Many walls and ledges here only open with later tools, so come back after each new upgrade: the FlameThrower, Lightning Gun, Multi-Disruptor and Orbital Discharge all hide here, and three passcodes open hidden doors (see Passcodes). In a room above the first chamber lie an old wheelchair and a faded note. Absu is below; Indi and Ukkin-Na are to the east.",
           "Tubos de ensayo con materia orgánica palpitante llenan estas cuevas: aquí la gente de Sudra reconstruía sus cuerpos. Trace encuentra el Axiom Disruptor en la sala contigua a su cámara de renacimiento, después el Nova, y se enfrenta a Xedur, que da el Laser Drill. Muchas paredes y salientes solo se abren con herramientas posteriores, así que conviene volver tras cada mejora: aquí se esconden el FlameThrower, el Lightning Gun, el Multi-Disruptor y el Orbital Discharge, y tres códigos abren puertas ocultas (ver Passcodes). En una sala sobre la primera cámara hay una vieja silla de ruedas y una nota descolorida. Debajo está Absu; al este, Indi y Ukkin-Na."},
          WIKI "Eribu", false},
    Entry{"absu", Kind::Place, {"Absu", "Absu"},
          {"An underground fungal forest wrapped around the ruins of an old prison.",
           "Un bosque subterráneo de hongos alrededor de las ruinas de una antigua prisión."},
          {"Here Trace meets Elsenova face to face for the first time; she gives him the Kilver, a short-range electric burst that goes through walls. Telal guards the area, and beating him leads to the Address Disruptor, the 'glitch gun' that defines the whole game. The lower prison is full of bones and Mutants. The Data Bomb and Inertial Pulse wait here for later visits, once Trace has the Remote Drone, Drone Teleport, Field Disruptor and Address Disruptor 2. Eribu and Indi are above, Zi to the east.",
           "Aquí Trace conoce por fin a Elsenova en persona; ella le da el Kilver, una descarga eléctrica de corto alcance que atraviesa paredes. Telal vigila la zona, y derrotarlo lleva al Address Disruptor, la «pistola de glitches» que define todo el juego. La prisión inferior está llena de huesos y mutantes. El Data Bomb y el Inertial Pulse esperan aquí para visitas posteriores, cuando Trace tenga el Remote Drone, el Drone Teleport, el Field Disruptor y el Address Disruptor 2. Encima están Eribu e Indi; al este, Zi."},
          WIKI "Absu", false},
    Entry{"zi", Kind::Place, {"Zi", "Zi"},
          {"The Rusalki's circulatory system, where the Power Filter must be restarted.",
           "El sistema circulatorio de los Rusalki, donde hay que reactivar el Power Filter."},
          {"Steam vents, pumps and organic caverns purify the fluids the Rusalki need to live. Elsenova sends Trace here to restart the Power Filter, which lies past the boss Uruku in the upper right; after it, the Modified Lab Coat in the far upper-right room lets him pass through thin walls. Veruska sleeps in the bottom-right corner, with the Passcode Tool hidden behind her. The Voranj and the first Bioflux Accelerator are also here. Warning: once Trace drops from Absu into Zi (the 'Jump of No Return'), he cannot jump back up until he has the Grapple.",
           "Respiraderos de vapor, bombas y cavernas orgánicas purifican los fluidos que los Rusalki necesitan para vivir. Elsenova envía aquí a Trace a reactivar el Power Filter, que está tras el jefe Uruku, arriba a la derecha; después, el Modified Lab Coat de la sala del extremo superior derecho le deja atravesar paredes finas. Veruska duerme en la esquina inferior derecha, con el Passcode Tool escondido detrás. También están aquí el Voranj y el primer Bioflux Accelerator. Aviso: cuando Trace baja de Absu a Zi (el «salto sin retorno»), no puede volver a subir hasta tener el Grapple."},
          WIKI "Zi", false},
    Entry{"kur", Kind::Place, {"Kur", "Kur"},
          {"Caverns that climb to Sudra's surface: the first sight of the sky and the Breach.",
           "Cavernas que suben a la superficie de Sudra: la primera vista del cielo y de la Brecha."},
          {"Kur rises from arid caves through forested slopes to icy peaks with falling snow, where the glitching Breach fills the upper sky. It is packed with upgrades: the Remote Drone in the centre, the Enhanced Drone Launch in the north, the Address Disruptor 2 above the lowest save room, the Field Disruptor, and the Grapple after the boss Gir-Tab, along with the Firewall, Reflector, Hypo-Atomizer, Ion Beam and Tethered Charge. Behind Gir-Tab lies Katrahaska's chamber and the switch for the Repair Drones. Beware the pink acid pools: they burn and Trace can drown in them.",
           "Kur sube desde cuevas áridas por laderas boscosas hasta picos helados con nieve, donde la Brecha llena de glitches ocupa el cielo. Está repleta de mejoras: el Remote Drone en el centro, el Enhanced Drone Launch al norte, el Address Disruptor 2 sobre la sala de guardado más baja, el Field Disruptor, y el Grapple tras el jefe Gir-Tab, además del Firewall, el Reflector, el Hypo-Atomizer, el Ion Beam y el Tethered Charge. Tras Gir-Tab están la cámara de Katrahaska y el interruptor de los drones de reparación. Cuidado con los charcos de ácido rosa: queman y Trace puede ahogarse en ellos."},  // codespell:ignore nieve
          WIKI "Kur", false},
    Entry{"indi", Kind::Place, {"Indi", "Indi"},
          {"Oracca's cavern: the central corridor that links most of Sudra.",
           "La caverna de Oracca: el pasillo central que une casi todo Sudra."},
          {"A long underground passage of green stone and moss that connects every area except E-Kur-Mah and Mar-Uru. The silent Rusalka Oracca wanders it and carries Trace across; stand on her head and she turns toward where he is heading. The Grapple is needed to get in. Using the Address Disruptor on a Blurst here (or in Ukkin-Na) can turn it into a hidden Health Node Fragment.",
           "Un largo pasaje subterráneo de piedra verde y musgo que conecta todas las zonas salvo E-Kur-Mah y Mar-Uru. La Rusalka muda Oracca lo recorre y lleva a Trace de un lado a otro; si te subes a su cabeza, se gira hacia donde quieres ir. Hace falta el Grapple para entrar. Usar el Address Disruptor sobre un Blurst aquí (o en Ukkin-Na) puede convertirlo en un fragmento de nodo de salud oculto."},  // codespell:ignore hace
          WIKI "Indi", false},
    Entry{"ukkin_na", Kind::Place, {"Ukkin-Na", "Ukkin-Na"},
          {"The Council Rock cliffs where Ophelia waits, and where strange things begin to happen.",
           "Los acantilados de la Roca del Consejo donde espera Ophelia, y donde empiezan a pasar cosas extrañas."},
          {"Soon after arriving, Trace begins to feel hot and faint, and the area turns into a long hallucination: faces, voices and enemies that can really hurt him. There is no way to skip it; dying sends him back to a chamber inside the area. Low walls block the way back until he finds the Trenchcoat, which lets him pass through thicker walls and in mid-air. Ophelia's head is in the upper part; her body lies in Edin. The Turbine Pulse is here too. Ukkin-Na links to Mar-Uru above, Indi below, Eribu west and Edin east.",
           "Poco después de llegar, Trace empieza a sentir calor y mareo, y la zona se convierte en una larga alucinación: caras, voces y enemigos que sí pueden herirle. No se puede saltar; morir le devuelve a una cámara dentro de la zona. Unos muros bajos impiden volver hasta encontrar el Trenchcoat, que le deja atravesar paredes más gruesas y en el aire. La cabeza de Ophelia está en la parte alta; su cuerpo, en Edin. Aquí está también el Turbine Pulse. Ukkin-Na conecta con Mar-Uru arriba, Indi abajo, Eribu al oeste y Edin al este."},
          WIKI "Ukkin-Na", false},
    Entry{"edin", Kind::Place, {"Edin", "Edin"},
          {"Grassy plains of ruins under a starry sky, with the remains of a giant Rusalka.",
           "Llanuras de hierba y ruinas bajo un cielo estrellado, con los restos de una Rusalka gigante."},
          {"With the Trenchcoat, most of Edin opens up. It holds the Address Bomb, the strongest corruption tool, the Drone Teleport after the boss Ukhu at the top, the second Bioflux Accelerator, and the Distortion Field and Shards. Near the exit to Indi a large hangar houses the Rusalki's bodies. Edin is also one of the places where the hard Secret World, with a rare weapon, can appear.",
           "Con el Trenchcoat se abre casi toda Edin. Aquí están el Address Bomb, la herramienta de corrupción más potente, el Drone Teleport tras el jefe Ukhu en lo alto, el segundo Bioflux Accelerator, y el Distortion Field y Shards. Cerca de la salida a Indi, un gran hangar guarda los cuerpos de los Rusalki. Edin es también uno de los lugares donde puede aparecer el mundo secreto difícil, con un arma rara."},
          WIKI "Edin", false},
    Entry{"e_kur_mah", Kind::Place, {"E-Kur-Mah", "E-Kur-Mah"},
          {"An ancient pyramid temple on the mountain top, at the edge of the Breach.",
           "Un antiguo templo piramidal en la cima de la montaña, al borde de la Brecha."},
          {"Its entrance is very high on the east side of Kur's surface: reach it with the Enhanced Drone Launch and the Drone Teleport. Powerful ancient Sentry Bots guard the upper halls; the Orbital Discharge is good against them because they get stuck on corners. Deep inside lies the Sudran Key, which opens the seals to the lower, overgrown levels, and at the very bottom the Red Coat. The Quantum Variegator hides behind a passcode spelled out by glitched plant enemies.",
           "Su entrada está muy alta, en el lado este de la superficie de Kur: se llega con el Enhanced Drone Launch y el Drone Teleport. Poderosos robots centinela antiguos vigilan las salas superiores; el Orbital Discharge funciona bien porque se atascan en las esquinas. En su interior está la Sudran Key, que abre los sellos hacia los niveles inferiores cubiertos de vegetación, y al fondo del todo el Red Coat. El Quantum Variegator se esconde tras un código que deletrean unas plantas al corromperlas."},
          WIKI "E-Kur-Mah", false},
    Entry{"mar_uru", Kind::Place, {"Mar-Uru", "Mar-Uru"},
          {"Athetos's hideout, high above Ukkin-Na at the fringe of the Breach.",
           "El escondite de Athetos, muy por encima de Ukkin-Na, en el borde de la Brecha."},
          {"The final area, reached from Ukkin-Na by climbing the elevator once Trace has the Red Coat. Ancient Sudran halls give way to a mechanical stronghold full of relentless machines. Sentinel blocks the climb, Xedur Hul waits near the top, and Athetos is at the end. The Reverse Slicer is down a corridor on the way. Save before the last stretch.",
           "La zona final, a la que se llega desde Ukkin-Na subiendo por el ascensor cuando Trace tiene el Red Coat. Las salas sudranas antiguas dan paso a una fortaleza mecánica llena de máquinas implacables. Sentinel bloquea la subida, Xedur Hul espera cerca de la cima y Athetos está al final. El Reverse Slicer está por un pasillo del camino. Guarda antes del último tramo."},
          WIKI "Mar-Uru", false},
    Entry{"secret_worlds", Kind::Place, {"Secret Worlds", "Mundos secretos"},
          {"Glitched pockets of reality hidden at random spots in every save.",
           "Bolsas de realidad corrupta escondidas en lugares aleatorios de cada partida."},
          {"Each save creates five: two easy ones (in Absu, Zi or Kur), two medium ones (Eribu, Indi or Ukkin-Na) and one hard one (Edin, E-Kur-Mah or Mar-Uru). Near an entrance, scanlines appear on the health bar and grow stronger as you get closer; corrupting the right spot opens it. Easy and medium worlds hold a Range or Size Node plus a Health Node Fragment. The hard one, sometimes a Red Coat puzzle, holds one of three rare weapons (Heat Seeker, Scissor Beam or Fat Beam), so only one can be had per playthrough. Elsenova warns Trace to turn back: the Rusalki cannot see inside. Speedrun Mode has none.",
           "Cada partida crea cinco: dos fáciles (en Absu, Zi o Kur), dos medios (Eribu, Indi o Ukkin-Na) y uno difícil (Edin, E-Kur-Mah o Mar-Uru). Cerca de una entrada aparecen líneas de barrido en la barra de salud, más intensas cuanto más te acercas; corromper el punto exacto la abre. Los fáciles y medios guardan un nodo de alcance o de tamaño y un fragmento de nodo de salud. El difícil, a veces un acertijo del Red Coat, guarda una de tres armas raras (Heat Seeker, Scissor Beam o Fat Beam), así que solo se consigue una por partida. Elsenova avisa a Trace de que se vuelva: los Rusalki no pueden ver dentro. El modo speedrun no tiene ninguno."},
          WIKI "Secret_World", false},

    // Characters
    Entry{"trace", Kind::Character, {"Trace", "Trace"},
          {"A scientist from Earth who wakes in an alien world after a lab accident.",
           "Un científico de la Tierra que despierta en un mundo alienígena tras un accidente de laboratorio."},
          {"Trace Eschenbrenner was working with Dr. Hammond at a New Mexico lab in 2005 when an explosion left him gravely hurt. He wakes in a Rebirth Chamber on Sudra, his body unharmed. He is a scientist, not a soldier: he defends himself but looks for knowledge, and his lines before and after boss fights show how hard he finds it to kill. Who he really is turns out to be one of the game's central questions.",
           "Trace Eschenbrenner trabajaba con la doctora Hammond en un laboratorio de Nuevo México en 2005 cuando una explosión le hirió de gravedad. Despierta en una cámara de renacimiento en Sudra, con el cuerpo intacto. Es científico, no soldado: se defiende pero busca conocimiento, y sus frases antes y después de los jefes muestran lo que le cuesta matar. Quién es en realidad acaba siendo una de las preguntas centrales del juego."},
          WIKI "Trace", false},
    Entry{"elsenova", Kind::Character, {"Elsenova", "Elsenova"},
          {"The first Rusalka Trace meets: a broken giant who becomes his guide.",
           "La primera Rusalka que conoce Trace: una gigante averiada que se convierte en su guía."},
          {"Her voice calls Trace from the first moment, telling him to take the gun in the next room. When he finds her in Absu she is a damaged head with a missing jaw, speaking broken English. She asks him to restart the Power Filter and the Repair Drones so the Rusalki can recover, and warns him to stay away from Athetos for now. She can watch him anywhere: the red particles that carry Trace back to a chamber when he dies are her nanogates. Whether she is a friend or something worse is left for the player to judge.",
           "Su voz llama a Trace desde el primer momento y le dice que coja el arma de la sala contigua. Cuando la encuentra en Absu es una cabeza dañada a la que le falta la mandíbula, que habla un inglés roto. Le pide reactivar el Power Filter y los drones de reparación para que los Rusalki se recuperen, y le advierte que por ahora se aleje de Athetos. Puede verle en cualquier parte: las partículas rojas que devuelven a Trace a una cámara al morir son sus nanogates. Si es una amiga o algo peor queda a juicio del jugador."},  // codespell:ignore momento
          WIKI "Elsenova", false},
    Entry{"ophelia", Kind::Character, {"Ophelia", "Ophelia"},
          {"A Rusalka in Ukkin-Na who speaks plain English and heals rather than fights.",
           "Una Rusalka de Ukkin-Na que habla un inglés claro y cura más que lucha."},
          {"Inactive until the Repair Drones are running, Ophelia waits in the upper part of Ukkin-Na; her body lies in Edin. She is kinder than Elsenova, more like a combat medic than a soldier, and explains a great deal about why Trace is on Sudra and what he should do next. Her name comes from Hamlet.",
           "Inactiva hasta que funcionan los drones de reparación, Ophelia espera en la parte alta de Ukkin-Na; su cuerpo está en Edin. Es más amable que Elsenova, más una médica de combate que una soldado, y explica mucho sobre por qué Trace está en Sudra y qué debe hacer después. Su nombre viene de Hamlet."},
          WIKI "Ophelia", false},
    Entry{"veruska", Kind::Character, {"Veruska", "Veruska"},
          {"'The Dreamer', a self-declared predator sleeping deep in Zi.",
           "«La Soñadora», una depredadora confesa que duerme en lo profundo de Zi."},
          {"Found in the bottom-right corner of Zi, barely functional. She speaks in riddles and metaphors and can build vivid dream worlds for others. Elsenova calls her dangerous but an ally. The Passcode Tool is stored behind her chamber; the Remote Drone is needed to reach it.",
           "Está en la esquina inferior derecha de Zi, casi sin funcionar. Habla con acertijos y metáforas y puede crear mundos de sueño muy vívidos para otros. Elsenova dice que es peligrosa pero aliada. El Passcode Tool está guardado tras su cámara; hace falta el Remote Drone para llegar."},  // codespell:ignore hace
          WIKI "Veruska", false},
    Entry{"oracca", Kind::Character, {"Oracca", "Oracca"},
          {"A mute Rusalka who ferries Trace through Indi.",
           "Una Rusalka muda que lleva a Trace a través de Indi."},
          {"Driven mad by long years of underground imprisonment, she wanders Indi and never speaks. Even so, she seems aware of Trace and carries him along the cavern, turning around when he does. The notes hint at a sad past involving Veruska and the Sudran priesthood.",
           "Enloquecida por largos años de encierro bajo tierra, recorre Indi y nunca habla. Aun así parece consciente de Trace y lo lleva por la caverna, dándose la vuelta cuando él lo hace. Las notas insinúan un pasado triste relacionado con Veruska y el sacerdocio sudrano."},  // codespell:ignore hace
          WIKI "Oracca", false},
    Entry{"daraga", Kind::Character, {"Daraga", "Daraga"},
          {"A small, silent Rusalka who appears briefly in Ukkin-Na.",
           "Una Rusalka pequeña y silenciosa que aparece un momento en Ukkin-Na."},  // codespell:ignore momento
          {"She floats in the room of the Vision fight for a short time afterwards. Firing the Remote Drone into her mouth makes her carry it up to the Turbine Pulse room, an early shortcut to that weapon.",
           "Flota en la sala del combate de Vision durante un rato después. Disparar el Remote Drone a su boca hace que lo lleve hasta la sala del Turbine Pulse, un atajo temprano a esa arma."},  // codespell:ignore hace
          WIKI "Daraga", false},
    Entry{"katrahaska", Kind::Character, {"Katrahaska", "Katrahaska"},
          {"A dead Rusalka whose torn-open head lies behind Gir-Tab in Kur.",
           "Una Rusalka muerta cuya cabeza abierta yace tras Gir-Tab en Kur."},
          {"All that remains is a lifeless shell. Elsenova says little about her and how she died; the notes say more for those who read them.",
           "Solo queda un caparazón sin vida. Elsenova dice poco de ella y de su muerte; las notas cuentan más a quien las lea."},
          WIKI "Katrahaska", false},
    Entry{"athetos", Kind::Character, {"Athetos", "Athetos"},
          {"The man the Rusalki blame for the death of every Sudran.",
           "El hombre al que los Rusalki culpan de la muerte de todos los sudranos."},
          {"According to the Rusalki, he released a pathogen that wiped out Sudra's people and then hid beyond their reach, guarding the Breach Attractor at the edge of the Breach. His nickname means something like 'one whose opinion is rejected'. Elsenova tells Trace to avoid him at first, yet everything points toward a meeting at the top of Mar-Uru. You get the feeling there is more to his story than the Rusalki say.",
           "Según los Rusalki, liberó un patógeno que acabó con la gente de Sudra y luego se ocultó fuera de su alcance, guardando el Breach Attractor en el borde de la Brecha. Su apodo significa algo así como «aquel cuya opinión se rechaza». Elsenova pide a Trace que lo evite al principio, pero todo apunta a un encuentro en lo alto de Mar-Uru. Da la sensación de que su historia es más de lo que cuentan los Rusalki."},
          WIKI "Athetos", false},
    Entry{"hammond", Kind::Character, {"Dr. Elizabeth Hammond", "Dra. Elizabeth Hammond"},
          {"Trace's colleague and friend at the New Mexico lab.",
           "La colega y amiga de Trace en el laboratorio de Nuevo México."},
          {"She was the only one who stood by Trace when other scientists rejected his ideas, and worked with him on the experiment that ends in the opening explosion. Her name returns in later notes about a company built on their research, which matters again in Axiom Verge 2.",
           "Fue la única que apoyó a Trace cuando otros científicos rechazaron sus ideas, y trabajó con él en el experimento que acaba en la explosión inicial. Su nombre reaparece en notas posteriores sobre una empresa creada con su investigación, que vuelve a importar en Axiom Verge 2."},  // codespell:ignore inicial
          WIKI "Doctor_Hammond", false},
    Entry{"rusalki", Kind::Character, {"The Rusalki", "Los Rusalki"},
          {"Giant biomechanical war machines with human faces and their own personalities.",
           "Gigantescas máquinas de guerra biomecánicas con rostro humano y personalidad propia."},
          {"All the Rusalki met are female: Elsenova, Veruska, Ophelia, Oracca, Daraga and the dead Katrahaska. The Sudrans called them Kuliltu and kept them imprisoned underground, separated from their bodies. They depend on the Power Filter and the Repair Drones to stay alive, write to each other in their own script, Vykhya, and can be poisoned and killed despite their size.",
           "Todas las Rusalki que aparecen son femeninas: Elsenova, Veruska, Ophelia, Oracca, Daraga y la difunta Katrahaska. Los sudranos las llamaban Kuliltu y las tenían encerradas bajo tierra, separadas de sus cuerpos. Dependen del Power Filter y de los drones de reparación para seguir vivas, se escriben en su propia escritura, el vykhya, y pueden ser envenenadas y morir pese a su tamaño."},  // codespell:ignore ser
          WIKI "Rusalki", false},
    Entry{"sudrans", Kind::Character, {"The Sudrans", "Los sudranos"},
          {"Sudra's vanished people, known only from bones and notes.",
           "El pueblo desaparecido de Sudra, conocido solo por huesos y notas."},
          {"Their ancestors built wonders such as the Rebirth Chambers and ways to cross the Breach. After a great collapse they became fearful and religious, revering 'Old Machines' they no longer understood. Their High Priestess could decide for the whole world, including surrounding Sudra with the Breach. Notes written in Sudran can be translated with the REVEAL-SUDRAN passcode.",
           "Sus antepasados construyeron maravillas como las cámaras de renacimiento y formas de cruzar la Brecha. Tras un gran colapso se volvieron temerosos y religiosos, venerando «máquinas antiguas» que ya no entendían. Su Suma Sacerdotisa podía decidir por todo el mundo, incluso rodear Sudra con la Brecha. Las notas en sudrano se traducen con el código REVEAL-SUDRAN."},
          WIKI "Sudran_(Race)", false},

    // Bosses
    Entry{"xedur", Kind::Boss, {"Xedur", "Xedur"},
          {"The first boss, in Eribu: an armoured creature with a bomb-dropping tail.",
           "El primer jefe, en Eribu: una criatura acorazada con una cola que suelta bombas."},
          {"It repeats a simple cycle: volleys of red orbs from its shell, then bombs from its tail. Its back and armour are immune; only the exposed flesh at the front takes damage. Use the two blocks in the room as cover, fire up or diagonally, and move to the opposite side when it crosses the room. Defeating it opens the way to the Laser Drill. (1,800 health.)",
           "Repite un ciclo sencillo: ráfagas de orbes rojos desde su caparazón y luego bombas desde la cola. Su espalda y su armadura son inmunes; solo la carne expuesta del frente recibe daño. Usa los dos bloques de la sala como cobertura, dispara hacia arriba o en diagonal, y cámbiate al lado opuesto cuando cruce la sala. Derrotarlo abre el camino al Laser Drill. (1800 de salud.)"},
          WIKI "Xedur", false},
    Entry{"telal", Kind::Boss, {"Telal", "Telal"},
          {"The second boss, in Absu: a hulking creature with a cannon like Trace's gun.",
           "El segundo jefe, en Absu: una mole con un cañón parecido al arma de Trace."},
          {"Trace tries to talk; Telal sees only a demon. It alternates small red spheres with huge laser shots, but its armour is so heavy that it moves in halting steps and cannot turn around in its chamber. Get behind it and it cannot hit you; its weak point is the cluster of yellow sacs on its back. (3,000 health.)",
           "Trace intenta hablar; Telal solo ve un demonio. Alterna pequeñas esferas rojas con enormes disparos láser, pero su armadura es tan pesada que avanza a trompicones y no puede darse la vuelta en su sala. Ponte detrás y no podrá alcanzarte; su punto débil es el grupo de sacos amarillos de la espalda. (3000 de salud.)"},
          WIKI "Telal", false},
    Entry{"uruku", Kind::Boss, {"Uruku", "Uruku"},
          {"The third boss, in Zi: a huge slug-like creature covered in weapons.",
           "El tercer jefe, en Zi: una enorme criatura con aspecto de babosa cubierta de armas."},
          {"It fires projectiles from its armaments and a high-energy laser from its shoulder cannon; each weapon can be destroyed by focusing fire on it. Afterwards, use the Address Disruptor to glitch the blocks in the room into platforms and cross to the Power Filter. (2,000 health.)",
           "Dispara proyectiles desde su armamento y un láser de alta energía desde el cañón del hombro; cada arma se puede destruir concentrando el fuego en ella. Después, usa el Address Disruptor para convertir los bloques de la sala en plataformas y cruzar hasta el Power Filter. (2000 de salud.)"},
          WIKI "Uruku", false},
    Entry{"gir_tab", Kind::Boss, {"Gir-Tab", "Gir-Tab"},
          {"The fourth boss, in Kur: a scorpion with cannon claws and a flamethrower tail.",
           "El cuarto jefe, en Kur: un escorpión con pinzas-cañón y una cola lanzallamas."},
          {"It fires volleys from its claws and back, walks back and forth, crouches, and sometimes leaps in to use its tail. Aim at the weak underbelly; its single eye is also a weak point but stays closed most of the time. It is the most talkative of these creatures. Behind it lie Katrahaska's chamber, the Repair Drones and the Grapple. (1,800 health.)",
           "Dispara ráfagas desde las pinzas y la espalda, avanza y retrocede, se agacha y a veces salta para usar la cola. Apunta al vientre, su punto débil; su único ojo también lo es, pero suele estar cerrado. Es la más habladora de estas criaturas. Tras ella están la cámara de Katrahaska, los drones de reparación y el Grapple. (1800 de salud.)"},
          WIKI "Gir-Tab", false},
    Entry{"ukhu", Kind::Boss, {"Ukhu", "Ukhu"},
          {"A giant wasp at the top of Edin, one of the hardest fights.",
           "Una avispa gigante en lo alto de Edin, uno de los combates más duros."},
          {"Its only weak point is its open mouth, and the windows are short. It spits purple sludge, stabs with its stinger and arms, and releases small wasps from its abdomen; those can be shot for health or glitched. Defeating it gives the Drone Teleport. (2,500 health.)",
           "Su único punto débil es la boca abierta, y las ocasiones son breves. Escupe lodo morado, ataca con el aguijón y los brazos, y suelta avispas pequeñas del abdomen; se pueden derribar para conseguir salud o corromperlas. Derrotarla da el Drone Teleport. (2500 de salud.)"},
          WIKI "Ukhu", false},
    Entry{"sentinel", Kind::Boss, {"Sentinel", "Sentinel"},
          {"A great machine hanging from the ceiling that blocks the climb in Mar-Uru.",
           "Una gran máquina colgada del techo que bloquea la subida en Mar-Uru."},
          {"When its beetle-like frame is open, it fires slow purple bolts in circles and sometimes a powerful directed beam; when closed, it is invulnerable. Shoot the pink eye in its centre while the frame is open. It seems to have been built by Athetos rather than by the Sudrans. (5,500 health.)",
           "Con su armazón de escarabajo abierto dispara lentos rayos morados en círculo y a veces un potente haz dirigido; cerrado, es invulnerable. Dispara al ojo rosa del centro mientras está abierto. Parece obra de Athetos más que de los sudranos. (5500 de salud.)"},
          WIKI "Sentinel", false},
    Entry{"xedur_hul", Kind::Boss, {"Xedur Hul", "Xedur Hul"},
          {"A fiercer Xedur near the top of Mar-Uru, and the only boss you can walk past.",
           "Un Xedur más feroz cerca de la cima de Mar-Uru, y el único jefe que se puede esquivar."},
          {"It attacks much faster than Xedur, aims every shot at Trace and leaves no cover in its room. Unlike every other boss, no laser wall closes the room: Trace even remarks on it. Walking past it to the far door is allowed, and sparing it earns the 'Mercy' achievement at the end. (6,000 health.)",
           "Ataca mucho más rápido que Xedur, apunta cada disparo a Trace y su sala no tiene cobertura. A diferencia del resto de jefes, ningún muro láser cierra la sala: el propio Trace lo comenta. Se permite pasar de largo hasta la puerta del fondo, y perdonarle da el logro «Mercy» al final. (6000 de salud.)"},
          WIKI "Xedur_Hul", false},
    Entry{"vision", Kind::Boss, {"Vision", "Vision"},
          {"A strange boss in Ukkin-Na where the roles are reversed.",
           "Un jefe extraño en Ukkin-Na donde se invierten los papeles."},
          {"At the end of the hallucination, the player controls the monster while another Trace shoots at it. It cannot be won; it ends with the monster's defeat and the story continues. To get through it quickly, hover just above the attacking Trace.",
           "Al final de la alucinación, el jugador controla al monstruo mientras otro Trace le dispara. No se puede ganar; termina con la derrota del monstruo y la historia continúa. Para acabar antes, quédate justo encima del Trace que dispara."},
          WIKI "Vision", true},
    Entry{"aborted_clone", Kind::Boss, {"Aborted Clone", "Aborted Clone"},
          {"A half-finished experiment found in Edin.",
           "Un experimento a medio terminar que se encuentra en Edin."},
          {"It does not attack, but touching it hurts. Break both red masses to trigger a scene; then Trace can shoot it or simply wait. Waiting until it dies on its own earns the 'Pacifist' trophy. What it is shakes Trace deeply.",
           "No ataca, pero tocarlo hace daño. Rompe las dos masas rojas para que empiece una escena; después Trace puede dispararle o simplemente esperar. Esperar a que muera por sí solo da el trofeo «Pacifist». Lo que es sacude profundamente a Trace."},  // codespell:ignore hace
          WIKI "Aborted_Clone", true},
    Entry{"athetos_fight", Kind::Boss, {"Athetos (final battle)", "Athetos (combate final)"},
          {"The last confrontation, at the top of Mar-Uru.",
           "El último enfrentamiento, en lo alto de Mar-Uru."},
          {"Athetos does not attack himself: he sits in a chamber that keeps him alive and sends Donaughts after Trace. Each time Trace weakens the Breach Attractor's power supply, the Breach retreats and Elsenova can rise higher to strike, so Athetos moves further up. After the fight, the outcome is not in Trace's hands.",
           "Athetos no ataca: está en una cámara que lo mantiene con vida y envía Donaughts contra Trace. Cada vez que Trace debilita la alimentación del Breach Attractor, la Brecha retrocede y Elsenova puede subir más para atacar, así que Athetos se desplaza más arriba. Tras el combate, el desenlace no está en manos de Trace."},
          WIKI "Athetos", true},
    Entry{"variants", Kind::Boss, {"The Variants", "Las Variantes"},  // codespell:ignore variantes
          {"What the bosses really are.",
           "Lo que son en realidad los jefes."},
          {"Xedur, Telal, Uruku, Gir-Tab, Ukhu, Xedur Hul and the Aborted Clone are all Variants: clones of Athetos made in the Rebirth Chambers and then modified with biomechanical and genetic changes. Several notes are their own journals as they transform. A strange sigil marks their lairs.",
           "Xedur, Telal, Uruku, Gir-Tab, Ukhu, Xedur Hul y el Aborted Clone son Variantes: clones de Athetos creados en las cámaras de renacimiento y luego modificados biomecánica y genéticamente. Varias notas son sus propios diarios mientras se transforman. Un extraño sello marca sus guaridas."},  // codespell:ignore variantes
          WIKI "Variant", true},

    // Weapons
    Entry{"axiom_disruptor", Kind::Item, {"Axiom Disruptor", "Axiom Disruptor"},
          {"Trace's gun: a long-range red shot, and the base for every other weapon.",
           "El arma de Trace: un disparo rojo de largo alcance, y la base de todas las demás."},
          {"Found in the room next to the first Rebirth Chamber in Eribu. Every other weapon is a program disc run by this gun, so new weapons change what it fires. Its plain shot stays useful all game for its range and accuracy.",
           "Está en la sala contigua a la primera cámara de renacimiento de Eribu. Todas las demás armas son discos de programa que ejecuta esta pistola, así que cada arma nueva cambia lo que dispara. Su disparo simple sigue siendo útil todo el juego por alcance y precisión."},
          WIKI "Axiom_Disruptor", false},
    Entry{"nova", Kind::Item, {"Nova", "Nova"},
          {"A large shot that bursts into six fragments when you fire again.",
           "Un disparo grande que estalla en seis fragmentos al volver a disparar."},
          {"The second weapon, in Eribu. Press once to launch it and again to detonate it into six projectiles, ideal for hitting enemies around corners or above ledges.",
           "La segunda arma, en Eribu. Pulsa una vez para lanzarlo y otra para detonarlo en seis proyectiles, ideal para alcanzar enemigos tras esquinas o sobre salientes."},
          WIKI "Nova", false},
    Entry{"kilver", Kind::Item, {"Kilver", "Kilver"},
          {"A short-range electric burst that fires through walls.",
           "Una descarga eléctrica de corto alcance que atraviesa paredes."},
          {"Given at the first meeting with Elsenova in Absu. It hits hard and, for most of the game, is the only weapon that goes through walls, so it can hit enemies that cannot hit back.",
           "Se obtiene en el primer encuentro con Elsenova en Absu. Pega fuerte y, durante casi todo el juego, es la única arma que atraviesa paredes, así que alcanza enemigos que no pueden devolver el golpe."},
          WIKI "Kilver", false},
    Entry{"multi_disruptor", Kind::Item, {"Multi-Disruptor", "Multi-Disruptor"},
          {"Three short shots at once: straight and two diagonals.",
           "Tres disparos cortos a la vez: recto y dos en diagonal."},
          {"Found high in Eribu's main shaft. Its range and damage are low; the Kilver usually does more up close.",
           "Está en lo alto del pozo principal de Eribu. Su alcance y daño son bajos; de cerca, el Kilver suele hacer más."},
          WIKI "Multi-Disruptor", false},
    Entry{"lightning_gun", Kind::Item, {"Lightning Gun", "Lightning Gun"},
          {"An electric arc that jumps to the nearest target.",
           "Un arco eléctrico que salta al objetivo más cercano."},
          {"Found in Eribu. Aim roughly toward an enemy and the arc finds it, which makes it very comfortable against small, fast creatures.",
           "Está en Eribu. Basta apuntar más o menos hacia un enemigo para que el arco lo alcance, muy cómodo contra criaturas pequeñas y rápidas."},
          WIKI "Lightning_Gun", false},
    Entry{"flamethrower", Kind::Item, {"FlameThrower", "FlameThrower"},
          {"A stream of flame that passes through walls; one of the best weapons.",
           "Un chorro de fuego que atraviesa paredes; una de las mejores armas."},
          {"In Eribu, left of the room where the Axiom Disruptor lies, behind breakable blocks; the DINGER-GISBAR passcode opens a wall in its room. Its wide area and short cooldown make it one of the most versatile weapons in the game.",
           "En Eribu, a la izquierda de la sala del Axiom Disruptor, tras bloques rompibles; el código DINGER-GISBAR abre una pared en su sala. Su gran área y su corta recarga la hacen una de las armas más versátiles del juego."},
          WIKI "FlameThrower", false},
    Entry{"orbital_discharge", Kind::Item, {"Orbital Discharge", "Orbital Discharge"},
          {"Spheres that cling to walls and run along them as blades.",
           "Esferas que se pegan a las paredes y las recorren como cuchillas."},
          {"Behind a hidden door in Eribu (passcode DALKHU-SUBTUM). Excellent against wall-crawlers such as Snailborgs and against E-Kur-Mah's Sentry Bots, which get caught on corners.",
           "Tras una puerta oculta de Eribu (código DALKHU-SUBTUM). Excelente contra enemigos que reptan por las paredes, como los Snailborg, y contra los robots centinela de E-Kur-Mah, que se atascan en las esquinas."},
          WIKI "Orbital_Discharge", false},
    Entry{"data_bomb", Kind::Item, {"Data Bomb", "Data Bomb"},
          {"A long-range shot whose explosion reaches through walls.",
           "Un disparo de largo alcance cuya explosión atraviesa paredes."},
          {"In a small room in Absu's lower left. It needs the Remote Drone launched from the bottom of Absu's leftmost shaft and the Drone Teleport, so it comes late.",
           "En una pequeña sala de la parte inferior izquierda de Absu. Hace falta lanzar el Remote Drone desde el fondo del pozo más a la izquierda de Absu y el Drone Teleport, así que llega tarde."},  // codespell:ignore hace
          WIKI "Data_Bomb", false},
    Entry{"inertial_pulse", Kind::Item, {"Inertial Pulse", "Inertial Pulse"},
          {"A dense beam that pierces through lines of enemies.",
           "Un haz denso que atraviesa filas de enemigos."},
          {"In Absu, across from its rightmost save room; the Address Disruptor 2 is needed to clear a glitched barrier in the room. Walls still block it.",
           "En Absu, frente a su sala de guardado más a la derecha; hace falta el Address Disruptor 2 para quitar una barrera corrupta de la sala. Las paredes sí lo detienen."},  // codespell:ignore hace
          WIKI "Inertial_Pulse", false},
    Entry{"voranj", Kind::Item, {"Voranj", "Voranj"},
          {"An energy bolt that keeps splitting into branches.",
           "Un rayo de energía que se ramifica una y otra vez."},
          {"In upper-left Zi, below the top-left save room. The branches spread around obstacles, but each split divides the damage.",
           "En la parte superior izquierda de Zi, bajo la sala de guardado de arriba a la izquierda. Las ramas rodean los obstáculos, pero cada división reparte el daño."},
          WIKI "Voranj", false},
    Entry{"firewall", Kind::Item, {"Firewall", "Firewall"},
          {"Bombs that erupt into pillars of fire.",
           "Bombas que estallan en columnas de fuego."},
          {"In Kur, in a wall next to the room with red wasps, reachable after the Field Disruptor. A bomb that lands on an enemy sticks to it and keeps burning.",
           "En Kur, en una pared junto a la sala de las avispas rojas, accesible tras el Field Disruptor. Una bomba que cae sobre un enemigo se le pega y sigue quemando."},  // codespell:ignore accesible
          WIKI "Firewall", false},
    Entry{"reflector", Kind::Item, {"Reflector", "Reflector"},
          {"Spinning shots that bounce off walls without limit.",
           "Disparos giratorios que rebotan en las paredes sin límite."},
          {"Found in Kur. Ideal in tight corridors: fire from cover and let the shots bounce into enemies.",
           "Está en Kur. Ideal en pasillos estrechos: dispara desde la cobertura y deja que los disparos reboten hasta los enemigos."},
          WIKI "Reflector", false},
    Entry{"hypo_atomizer", Kind::Item, {"Hypo-Atomizer", "Hypo-Atomizer"},
          {"Shots that keep releasing smaller shots up and down.",
           "Disparos que van soltando disparos menores hacia arriba y hacia abajo."},
          {"Found in Kur. Fired sideways, each projectile spits two perpendicular shots at regular distances, covering platforms above and below.",
           "Está en Kur. Disparado de lado, cada proyectil suelta dos disparos perpendiculares cada cierta distancia, cubriendo plataformas por encima y por debajo."},
          WIKI "Hypo-Atomizer", false},
    Entry{"ion_beam", Kind::Item, {"Ion Beam", "Ion Beam"},
          {"A continuous long red laser.",
           "Un láser rojo largo y continuo."},
          {"In the middle of Kur, in the large open area. Hold the button to keep firing; aiming upward while walking draws out and kills flying enemies off screen.",
           "En el centro de Kur, en la gran zona abierta. Mantén el botón para seguir disparando; apuntar hacia arriba mientras caminas atrae y elimina enemigos voladores fuera de pantalla."},
          WIKI "Ion_Beam", false},
    Entry{"tethered_charge", Kind::Item, {"Tethered Charge", "Tethered Charge"},
          {"An energy orb on a leash that you can steer around obstacles.",
           "Un orbe de energía atado que se puede dirigir alrededor de obstáculos."},
          {"Found in Kur. It flies out and returns like a yo-yo and can be re-aimed in flight. It is the only weapon that can pick up health drops by shooting them.",
           "Está en Kur. Sale y vuelve como un yoyó y se puede redirigir en vuelo. Es la única arma que recoge la salud al dispararle."},
          WIKI "Tethered_Charge", false},
    Entry{"turbine_pulse", Kind::Item, {"Turbine Pulse", "Turbine Pulse"},
          {"Spinning particles that fly off as pulses when you let go.",
           "Partículas giratorias que salen disparadas al soltar el botón."},
          {"In Ukkin-Na; Daraga can carry the Remote Drone up to it early. Hold to spin four particles in front of Trace, release to send them forward.",
           "En Ukkin-Na; Daraga puede subir el Remote Drone hasta ella antes de tiempo. Mantén pulsado para hacer girar cuatro partículas delante de Trace y suelta para lanzarlas."},
          WIKI "Turbine_Pulse", false},
    Entry{"distortion_field", Kind::Item, {"Distortion Field", "Distortion Field"},
          {"A short circular warp that passes through walls and stuns.",
           "Una distorsión circular corta que atraviesa paredes y aturde."},
          {"In central Edin, in a room full of Jorms left of the rightmost save room; corrupting the Jorms helps. Like the Kilver, but it can be held down.",
           "En el centro de Edin, en una sala llena de Jorms a la izquierda de la sala de guardado más a la derecha; corromper a los Jorms ayuda. Como el Kilver, pero se puede mantener pulsado."},
          WIKI "Distortion_Field", false},
    Entry{"shards", Kind::Item, {"Shards", "Shards"},
          {"A rapid cone of ice shards.",
           "Un cono rápido de esquirlas de hielo."},
          {"In the lower right of Edin's large bottom-left room. Up to 32 shards fly at once and stick briefly in walls and enemies.",
           "En la parte inferior derecha de la gran sala de abajo a la izquierda de Edin. Hasta 32 esquirlas a la vez, que se clavan un momento en paredes y enemigos."},  // codespell:ignore momento
          WIKI "Shards", false},
    Entry{"quantum_variegator", Kind::Item, {"Quantum Variegator", "Quantum Variegator"},
          {"Rapid shots that wander randomly as they fly.",
           "Disparos rápidos que cambian de rumbo al azar."},
          {"In E-Kur-Mah, behind a wall opened by the ISKART-EHANZU passcode, which glitched plant enemies in that room spell out. The spread grows the longer you hold the button.",
           "En E-Kur-Mah, tras una pared que abre el código ISKART-EHANZU, que deletrean las plantas corruptas de esa sala. La dispersión crece cuanto más tiempo mantienes el botón."},
          WIKI "Quantum_Variegator", false},
    Entry{"reverse_slicer", Kind::Item, {"Reverse Slicer", "Reverse Slicer"},
          {"A crescent blade that flies out through walls and comes back.",
           "Una cuchilla en media luna que atraviesa paredes y vuelve."},
          {"In Mar-Uru, down a hallway on the way up. It boomerangs back to where it was fired and passes through walls, though breakable blocks stop it.",
           "En Mar-Uru, por un pasillo del camino de subida. Vuelve como un bumerán al punto de disparo y atraviesa paredes, aunque los bloques rompibles la detienen."},
          WIKI "Reverse_Slicer", false},
    Entry{"heat_seeker", Kind::Item, {"Heat Seeker", "Heat Seeker"},
          {"Rapid shots that home in on enemies; only in the hard Secret World.",
           "Disparos rápidos que buscan a los enemigos; solo en el mundo secreto difícil."},
          {"One of three weapons that only the hard Secret World can contain, so a save gets either this, the Scissor Beam or the Fat Beam.",
           "Una de las tres armas que solo puede contener el mundo secreto difícil, así que cada partida consigue esta, el Scissor Beam o el Fat Beam."},  // codespell:ignore contener
          WIKI "Heat_Seeker", false},
    Entry{"scissor_beam", Kind::Item, {"Scissor Beam", "Scissor Beam"},
          {"Twin beams that close on a point; only in the hard Secret World.",
           "Dos haces que convergen en un punto; solo en el mundo secreto difícil."},
          {"Passes through walls, has a long range for such a weapon, and can be re-aimed after firing.",
           "Atraviesa paredes, tiene mucho alcance para un arma así y se puede reorientar tras disparar."},
          WIKI "Scissor_Beam", false},
    Entry{"fat_beam", Kind::Item, {"Fat Beam", "Fat Beam"},
          {"A huge beam after a targeting delay; only in the hard Secret World.",
           "Un haz enorme tras un retardo de apuntado; solo en el mundo secreto difícil."},
          {"Hold to aim a thin laser for two seconds, then a beam wider than Trace fires for four seconds through walls.",
           "Mantén pulsado para apuntar un láser fino durante dos segundos; después sale un haz más ancho que Trace durante cuatro segundos, a través de las paredes."},
          WIKI "Fat_Beam", false},

    // Tools and upgrades
    Entry{"laser_drill", Kind::Ability, {"Laser Drill", "Laser Drill"},
          {"Cuts through breakable rock in all eight directions.",
           "Corta roca rompible en las ocho direcciones."},
          {"The reward for beating Xedur. Most breakable blocks look different, but not all; to drill down, jump and hold down. It also hurts enemies and is effective against armoured ones.",
           "La recompensa por vencer a Xedur. La mayoría de bloques rompibles se distinguen, pero no todos; para perforar hacia abajo, salta y mantén abajo. También daña a los enemigos y funciona contra los acorazados."},
          WIKI "Laser_Drill", false},
    Entry{"address_disruptor", Kind::Ability, {"Address Disruptor", "Address Disruptor"},
          {"The 'glitch gun': corrupts and un-corrupts blocks and enemies.",
           "La «pistola de glitches»: corrompe y descorrompe bloques y enemigos."},
          {"Found in Absu after Telal. It fires a cone of blue rectangles that change what they touch: glitched blocks may become passable or solid, and glitched enemies change their behaviour, often becoming easier to beat or even useful. The Address Disruptor 2, in lower Kur, replaces it with a stronger red version that affects more things.",
           "Está en Absu tras Telal. Dispara un cono de rectángulos azules que cambia lo que toca: los bloques corruptos pueden volverse atravesables o sólidos, y los enemigos corruptos cambian de comportamiento, a menudo más fáciles de vencer o incluso útiles. El Address Disruptor 2, en la parte baja de Kur, lo sustituye por una versión roja más potente que afecta a más cosas."},
          WIKI "Address_Disruptor_1", false},
    Entry{"address_bomb", Kind::Ability, {"Address Bomb", "Address Bomb"},
          {"The strongest corruption tool: a slow bomb that glitches a whole area.",
           "La herramienta de corrupción más potente: una bomba lenta que corrompe toda una zona."},
          {"Found in Edin. It needs bomb ammo, which enemies start dropping once Trace has it; he can carry three. It handles the toughest corrupted blocks and enemies.",
           "Está en Edin. Necesita munición de bomba, que los enemigos empiezan a soltar cuando Trace la tiene; puede llevar tres. Se encarga de los bloques y enemigos más corruptos."},
          WIKI "Address_Bomb", false},
    Entry{"field_disruptor", Kind::Ability, {"Field Disruptor", "Field Disruptor"},
          {"A higher jump: from four blocks to six.",
           "Un salto más alto: de cuatro bloques a seis."},
          {"Found in lower Kur, reached through Zi early on. It opens many ledges, but not the jump from Zi back to Absu; that needs the Grapple.",
           "Está en la parte baja de Kur, a la que se llega pronto desde Zi. Abre muchos salientes, pero no el salto de Zi de vuelta a Absu; para eso hace falta el Grapple."},  // codespell:ignore hace
          WIKI "Field_Disruptor", false},
    Entry{"grapple", Kind::Ability, {"Grapple", "Grapple"},
          {"A biomechanical hook to swing from ceilings and walls.",
           "Un gancho biomecánico para balancearse desde techos y paredes."},
          {"In Kur's large upper-right room, after Gir-Tab. Fire it straight up or diagonally, hang, climb, swing and jump off. It is needed to get back to Absu from Zi and to enter Indi, and it also hurts enemies.",
           "En la gran sala superior derecha de Kur, tras Gir-Tab. Se dispara hacia arriba o en diagonal para colgarse, trepar, balancearse y saltar. Hace falta para volver a Absu desde Zi y para entrar en Indi, y también daña a los enemigos."},  // codespell:ignore hace
          WIKI "Grapple", false},
    Entry{"remote_drone", Kind::Ability, {"Remote Drone", "Remote Drone"},
          {"A small walking drone for tight spaces; Trace is protected while using it.",
           "Un pequeño dron con patas para espacios estrechos; Trace queda protegido mientras lo usa."},
          {"In the centre of Kur. The drone hatches from an egg fired by the gun, has its own health and a short drill, and fits where Trace cannot. Rebirth Chambers do not repair it. The Enhanced Drone Launch fires the egg much further, and the Drone Teleport moves Trace to the drone.",
           "En el centro de Kur. El dron sale de un huevo disparado por el arma, tiene su propia salud y un taladro corto, y cabe donde Trace no. Las cámaras de renacimiento no lo reparan. El Enhanced Drone Launch lanza el huevo mucho más lejos, y el Drone Teleport lleva a Trace hasta el dron."},
          WIKI "Remote_Drone", false},
    Entry{"drone_teleport", Kind::Ability, {"Drone Teleport", "Drone Teleport"},
          {"Teleports Trace to his Remote Drone.",
           "Teletransporta a Trace hasta su Remote Drone."},
          {"The reward for beating Ukhu in Edin. With the Enhanced Drone Launch it reaches very high ledges, including the entrance to E-Kur-Mah, and it makes the Drone Climbing technique possible.",
           "La recompensa por vencer a Ukhu en Edin. Con el Enhanced Drone Launch alcanza salientes muy altos, incluida la entrada a E-Kur-Mah, y permite la técnica de escalada con el dron."},
          WIKI "Drone_Teleport", false},
    Entry{"lab_coats", Kind::Ability, {"Lab Coats", "Batas"},
          {"Three coats that let Trace teleport through walls and take less damage.",
           "Tres batas que permiten a Trace teletransportarse a través de paredes y recibir menos daño."},
          {"The Modified Lab Coat (Zi, after Uruku) passes one-block walls: double-tap and hold against a wall. The Trenchcoat (Ukkin-Na) passes two-block walls, works in mid-air and in every direction. The Red Coat (bottom of E-Kur-Mah) passes three-block walls, damages tiles and enemies in its path, and opens the way to Mar-Uru. Each coat also reduces damage: 40% taken with the first two, 30% with the Red Coat.",
           "La Modified Lab Coat (Zi, tras Uruku) atraviesa paredes de un bloque: doble toque y mantener contra la pared. La Trenchcoat (Ukkin-Na) atraviesa paredes de dos bloques, en el aire y en todas direcciones. La Red Coat (fondo de E-Kur-Mah) atraviesa paredes de tres bloques, daña bloques y enemigos a su paso y abre el camino a Mar-Uru. Cada bata reduce también el daño: se recibe un 40 % con las dos primeras y un 30 % con la Red Coat."},  // codespell:ignore doble
          WIKI "Modified_Lab_Coat", false},
    Entry{"passcode_tool", Kind::Ability, {"Passcode Tool", "Passcode Tool"},
          {"Rewrites reality with twelve-letter codes found in notes and walls.",
           "Reescribe la realidad con códigos de doce letras hallados en notas y paredes."},
          {"Stored behind Veruska in Zi. Codes have the form XXXXXX-XXXXXX and are entered from the menu; up to five can be active. Some translate languages, others reveal doors. See the Passcodes card for the useful ones.",
           "Guardado tras Veruska en Zi. Los códigos tienen la forma XXXXXX-XXXXXX y se introducen desde el menú; puede haber hasta cinco activos. Unos traducen idiomas y otros revelan puertas. Consulta la ficha Passcodes para los útiles."},
          WIKI "Passcode_Tool", false},
    Entry{"sudran_key", Kind::Ability, {"Sudran Key", "Sudran Key"},
          {"An ancient key that opens the seals in E-Kur-Mah.",
           "Una llave antigua que abre los sellos de E-Kur-Mah."},
          {"Found deep in E-Kur-Mah's upper halls. It raises the barriers to the lower temple, where the Red Coat lies.",
           "Está en lo profundo de las salas superiores de E-Kur-Mah. Levanta las barreras hacia el templo inferior, donde está la Red Coat."},
          WIKI "Sudran_Key", false},
    Entry{"bioflux", Kind::Ability, {"Bioflux Accelerator", "Bioflux Accelerator"},
          {"A mutation that grows firing tentacles while Trace is at full health.",
           "Una mutación que hace brotar tentáculos que disparan mientras Trace tiene la salud al máximo."},  // codespell:ignore hace
          {"The first is in Zi, the second in Edin. At full health, two (later four) tentacles grow from Trace's back and fire straight ahead whenever he shoots.",
           "El primero está en Zi y el segundo en Edin. Con la salud al máximo, dos (después cuatro) tentáculos salen de la espalda de Trace y disparan hacia delante cada vez que él dispara."},
          WIKI "Bioflux_Accelerator", false},
    Entry{"nodes", Kind::Ability, {"Nodes and fragments", "Nodos y fragmentos"},
          {"Permanent upgrades for health, damage, range and projectile size.",
           "Mejoras permanentes de salud, daño, alcance y tamaño de los proyectiles."},
          {"A Health Node adds 100 health; five Health Node Fragments make one more. Power Nodes raise weapon damage: there are nine, six whole ones plus three built from 18 fragments. Range Nodes and Size Nodes lengthen and enlarge the shots of the weapons they affect. Many are hidden behind walls that need later tools, and Secret Worlds hold several.",
           "Un nodo de salud añade 100 de salud; cinco fragmentos de nodo de salud forman otro. Los nodos de poder aumentan el daño de las armas: hay nueve, seis enteros y tres formados con 18 fragmentos. Los nodos de alcance y de tamaño alargan y agrandan los disparos de las armas a las que afectan. Muchos están tras paredes que requieren herramientas posteriores, y los mundos secretos guardan varios."},  // codespell:ignore varios
          WIKI "Health_Node", false},

    // Tips and mechanics
    Entry{"main_path", Kind::Guide, {"Main path", "Camino principal"},
          {"The order in which the required steps usually happen.",
           "El orden en que suelen ocurrir los pasos obligatorios."},
          {"Axiom Disruptor and Nova, Xedur, Laser Drill; Elsenova and the Kilver; Telal and the Address Disruptor; the 'Jump of No Return' into Zi; Field Disruptor, Uruku, the Power Filter and the Modified Lab Coat; Remote Drone and Address Disruptor 2; Gir-Tab, the Repair Drones and the Grapple; Ukkin-Na and the Trenchcoat; Edin's Address Bomb, Ukhu and the Drone Teleport; E-Kur-Mah's Sudran Key and Red Coat; then Mar-Uru. When you feel stuck, look for the next item on this list.",
           "Axiom Disruptor y Nova, Xedur, Laser Drill; Elsenova y el Kilver; Telal y el Address Disruptor; el «salto sin retorno» a Zi; Field Disruptor, Uruku, el Power Filter y la Modified Lab Coat; Remote Drone y Address Disruptor 2; Gir-Tab, los drones de reparación y el Grapple; Ukkin-Na y la Trenchcoat; el Address Bomb de Edin, Ukhu y el Drone Teleport; la Sudran Key y la Red Coat de E-Kur-Mah; y después Mar-Uru. Si te atascas, busca el siguiente objeto de esta lista."},
          WIKI "Main_Sequence", false},
    Entry{"corruption", Kind::Guide, {"Corruption (glitches)", "Corrupción (glitches)"},
          {"How glitched blocks and enemies work.",
           "Cómo funcionan los bloques y enemigos corruptos."},
          {"Near the Breach, matter on Sudra can be rewritten. There are three levels of corruption: the Address Disruptor handles level 1, the Address Disruptor 2 level 2, and the Address Bomb level 3. Corrupting a block can open a path or close one, and corrupting an enemy changes how it behaves; some become platforms, some lose their attacks. The most corrupted terrain hurts on contact. Try the Address Disruptor on anything that looks odd.",
           "Cerca de la Brecha, la materia de Sudra se puede reescribir. Hay tres niveles de corrupción: el Address Disruptor afecta al nivel 1, el Address Disruptor 2 al nivel 2 y el Address Bomb al nivel 3. Corromper un bloque puede abrir o cerrar un camino, y corromper un enemigo cambia su comportamiento; algunos se vuelven plataformas y otros pierden sus ataques. El terreno más corrupto hace daño al tocarlo. Prueba el Address Disruptor en todo lo que parezca raro."},  // codespell:ignore hace
          WIKI "Corruption", false},
    Entry{"passcodes", Kind::Guide, {"Passcodes", "Passcodes (códigos)"},
          {"Useful codes for the Passcode Tool.",
           "Códigos útiles para el Passcode Tool."},
          {"REVEAL-SUDRAN and REVEAL-VYKHYA translate notes in those languages. DINGER-GISBAR opens a wall in Eribu's FlameThrower room; IKKIBU-LABIRU reveals a door to a Power Node Fragment in upper-left Eribu; DALKHU-SUBTUM opens the Orbital Discharge room in Eribu; ISKART-EHANZU opens the Quantum Variegator wall in E-Kur-Mah. TRACK0-000000 to TRACK0-000018 play the music, and CUTSCE-NE0001 to 0044 replay scenes (save first). JUSTIN-BAILEY changes Trace's outfit. Codes starting with AXIO are cheats: they disable trophies.",
           "REVEAL-SUDRAN y REVEAL-VYKHYA traducen las notas en esos idiomas. DINGER-GISBAR abre una pared en la sala del FlameThrower de Eribu; IKKIBU-LABIRU revela una puerta a un fragmento de nodo de poder arriba a la izquierda de Eribu; DALKHU-SUBTUM abre la sala del Orbital Discharge en Eribu; ISKART-EHANZU abre la pared del Quantum Variegator en E-Kur-Mah. De TRACK0-000000 a TRACK0-000018 suena la música, y de CUTSCE-NE0001 a 0044 se repiten escenas (guarda antes). JUSTIN-BAILEY cambia la ropa de Trace. Los códigos que empiezan por AXIO son trucos: desactivan los trofeos."},
          WIKI "Passcodes", false},
    Entry{"rebirth_chambers", Kind::Guide, {"Rebirth Chambers", "Cámaras de renacimiento"},
          {"The egg-shaped save points: heal, refill bombs and come back after dying.",
           "Los puntos de guardado con forma de huevo: curan, recargan bombas y devuelven a Trace al morir."},
          {"Entering one saves, fully heals and refills bomb ammo. When Trace dies, the red particles of his nanogates carry him back to the last chamber used. Chamber rooms never hide items, so there is no need to drill their walls.",
           "Entrar en una guarda, cura por completo y recarga la munición de bombas. Cuando Trace muere, las partículas rojas de sus nanogates lo devuelven a la última cámara usada. Las salas de las cámaras nunca esconden objetos, así que no hace falta perforar sus paredes."},  // codespell:ignore hace
          WIKI "Rebirth_Chamber", false},
    Entry{"drone_climbing", Kind::Guide, {"Drone Climbing", "Escalada con el dron"},
          {"An advanced trick to gain unlimited height with the Drone Teleport.",
           "Un truco avanzado para ganar altura sin límite con el Drone Teleport."},
          {"Launch the drone, teleport to it near the top of its arc and launch it again. Teleporting normally blocks a new launch, but using the drill resets the cooldown, so the rhythm is drone, drone, drill, drone: on Switch, X, X, ZR, X by default. It is mostly a speedrun technique.",
           "Lanza el dron, teletranspórtate a él cerca de lo alto de su arco y lánzalo de nuevo. Teletransportarse normalmente impide lanzar otra vez, pero usar el taladro reinicia la espera, así que el ritmo es dron, dron, taladro, dron: en Switch, X, X, ZR, X por defecto. Es sobre todo una técnica de speedrun."},
          WIKI "Drone_Climbing", false},
    Entry{"notes", Kind::Guide, {"Notes", "Notas"},
          {"Hidden notes that tell most of the real story.",
           "Notas ocultas que cuentan la mayor parte de la historia real."},
          {"Notes from Sudrans, Rusalki, Variants and others are scattered across Sudra. They are often more reliable than what the characters tell Trace. Notes in Sudran or Vykhya need the REVEAL-SUDRAN or REVEAL-VYKHYA passcode, and some contain other passcodes.",
           "Notas de sudranos, Rusalki, Variantes y otros están repartidas por Sudra. Suelen ser más fiables que lo que los personajes cuentan a Trace. Las notas en sudrano o vykhya necesitan el código REVEAL-SUDRAN o REVEAL-VYKHYA, y algunas contienen otros códigos."},  // codespell:ignore ser,variantes
          WIKI "Notes", false},
    Entry{"modes", Kind::Guide, {"Hard and Speedrun modes", "Modos difícil y speedrun"},
          {"What changes in the alternative modes.",
           "Qué cambia en los modos alternativos."},  // codespell:ignore alternativos
          {"Hard Mode: enemies drop health 25% less often and it heals 25% less, bosses move 25% faster, Trace's weapons do 90% damage and enemies hit 10% harder. Speedrun Mode removes dialogue, cutscenes and randomness, adds a timer, changes health drops and has no Secret Worlds, so the three rare weapons are missing.",
           "Modo difícil: los enemigos sueltan salud un 25 % menos y cura un 25 % menos, los jefes se mueven un 25 % más rápido, las armas de Trace hacen un 90 % del daño y los enemigos pegan un 10 % más. El modo speedrun quita diálogos, escenas y azar, añade un cronómetro, cambia la salud que sueltan los enemigos y no tiene mundos secretos, así que faltan las tres armas raras."},
          WIKI "Hard_Mode", false},
    Entry{"sequence_breaks", Kind::Guide, {"Skips", "Atajos"},
          {"Two known ways to skip parts of the main path.",
           "Dos formas conocidas de saltarse partes del camino principal."},
          {"The Grapple Skip returns to Eribu from beyond the 'Jump of No Return' without the Grapple, avoiding Gir-Tab, Katrahaska and the Repair Drones. The Bomb Skip avoids the Aborted Clone and what follows it. Both are optional tricks for experienced players.",
           "El Grapple Skip vuelve a Eribu desde más allá del «salto sin retorno» sin el Grapple, evitando a Gir-Tab, a Katrahaska y los drones de reparación. El Bomb Skip evita al Aborted Clone y lo que le sigue. Ambos son trucos opcionales para jugadores con experiencia."},
          WIKI "Sequence_Break", false},

    // Story and lore
    Entry{"sudra", Kind::Timeline, {"Sudra", "Sudra"},
          {"The world of the game: once a gateway between universes.",
           "El mundo del juego: en otro tiempo, una puerta entre universos."},
          {"Hundreds of years ago Sudra was a port to advanced civilisations, a world built to keep the Breach under control. Its people slowly lost their understanding of their own technology, the gateway closed and Sudra fell into isolation, holding its machines in religious awe. Its air is breathable, and it has plants, animals and snow, but its people are gone.",
           "Hace cientos de años Sudra era un puerto hacia civilizaciones avanzadas, un mundo hecho para mantener la Brecha bajo control. Su gente fue perdiendo la comprensión de su propia tecnología, la puerta se cerró y Sudra cayó en el aislamiento, tratando sus máquinas con temor religioso. Su aire es respirable y tiene plantas, animales y nieve, pero su gente ya no está."},  // codespell:ignore hace,nieve
          WIKI "Sudra", false},
    Entry{"breach", Kind::Timeline, {"The Breach", "La Brecha (Breach)"},
          {"The storm between universes that surrounds Sudra.",
           "La tormenta entre universos que rodea Sudra."},
          {"A vast, little-understood storm that both separates and connects worlds. It can be crossed, but it is deadly without protection and damages technology. The glitchy band visible in Kur's and Edin's skies is how it shows itself; Sudrans called it 'the storm'. Its closeness is why matter on Sudra can be corrupted.",
           "Una tormenta inmensa y poco comprendida que separa y a la vez conecta mundos. Se puede cruzar, pero es mortal sin protección y daña la tecnología. La franja llena de glitches que se ve en el cielo de Kur y Edin es su manifestación; los sudranos la llamaban «la tormenta». Su cercanía explica que la materia de Sudra pueda corromperse."},
          WIKI "Breach", false},
    Entry{"breach_attractor", Kind::Timeline, {"Breach Attractor", "Breach Attractor"},
          {"The 'storm talisman' that pulled the Breach tight around Sudra.",
           "El «talismán de la tormenta» que ciñó la Brecha alrededor de Sudra."},
          {"A Sudran High Priestess used it to bring the Breach down to the planet's surface. The Rusalki cannot pass the Breach, so it forced them into hiding underground. Athetos now guards it at the top of Mar-Uru.",
           "Una Suma Sacerdotisa sudrana lo usó para hacer bajar la Brecha hasta la superficie del planeta. Los Rusalki no pueden atravesar la Brecha, así que los obligó a esconderse bajo tierra. Athetos lo custodia ahora en lo alto de Mar-Uru."},
          WIKI "Breach_Attractor", false},
    Entry{"nanogates", Kind::Timeline, {"Nanogates", "Nanogates"},
          {"The tiny machines inside Trace that link him to the Rusalki.",
           "Las diminutas máquinas dentro de Trace que lo unen a los Rusalki."},
          {"They let Elsenova talk to Trace and see where he is, help heal him, and are the red swarm that carries him back to a Rebirth Chamber after death.",
           "Permiten a Elsenova hablar con Trace y ver dónde está, ayudan a curarlo y son el enjambre rojo que lo devuelve a una cámara de renacimiento al morir."},
          WIKI "Nanogates", false},
    Entry{"pathogen", Kind::Timeline, {"The Pathogen", "El patógeno"},
          {"The plague that wiped out and mutated the Sudrans.",
           "La plaga que exterminó y mutó a los sudranos."},
          {"The Rusalki blame Athetos for it. Its effects reach Trace too: a brief second Trace can be glimpsed in Zi, and in Ukkin-Na it causes a long hallucination. A Sudran 'Security Notice' says only that the intruder who took the storm talisman is suspected.",
           "Los Rusalki culpan de ella a Athetos. Sus efectos alcanzan también a Trace: en Zi se puede ver fugazmente a un segundo Trace, y en Ukkin-Na provoca una larga alucinación. Un «aviso de seguridad» sudrano dice solo que se sospecha del intruso que se llevó el talismán de la tormenta."},
          WIKI "Pathogen", false},
    Entry{"story_start", Kind::Timeline, {"The story so far", "La historia hasta ahora"},
          {"The premise, without spoilers.",
           "El planteamiento, sin spoilers."},
          {"After the lab explosion, Trace wakes on Sudra. Elsenova, a crippled Rusalka, explains that Athetos released a plague that killed every Sudran and trapped the Rusalki. To help them, and to find a way home, Trace restarts the Power Filter that cleans their life fluids, then the Repair Drones that mend their bodies, and finally sets out to stop Athetos and the Breach Attractor. Along the way the notes, the bosses' words and the world itself raise doubts about what he is being told.",
           "Tras la explosión del laboratorio, Trace despierta en Sudra. Elsenova, una Rusalka lisiada, le explica que Athetos liberó una plaga que mató a todos los sudranos y atrapó a los Rusalki. Para ayudarles, y para encontrar la forma de volver a casa, Trace reactiva el Power Filter que limpia sus fluidos vitales, después los drones de reparación que arreglan sus cuerpos, y por último sale a detener a Athetos y el Breach Attractor. Por el camino, las notas, las palabras de los jefes y el propio mundo siembran dudas sobre lo que le cuentan."},
          WIKI "Story", false},
    Entry{"trace_identity", Kind::Timeline, {"Who Trace really is", "Quién es Trace en realidad"},
          {"The game's central revelation.",
           "La gran revelación del juego."},
          {"The Trace you play is a clone. Long ago, the original Trace (Athetos) used a Rebirth Chamber and left an imprint of himself. Ophelia proposed using it to create a younger Athetos who might side with the Rusalki, and Katrahaska's nanogates were placed inside him. His memories of the lab explosion are inherited; the explosion never happened to him.",
           "El Trace que manejas es un clon. Hace mucho, el Trace original (Athetos) usó una cámara de renacimiento y dejó una huella de sí mismo. Ophelia propuso usarla para crear un Athetos joven que quizá se pusiera de parte de los Rusalki, y le implantaron los nanogates de Katrahaska. Sus recuerdos de la explosión son heredados; a él nunca le ocurrió."},  // codespell:ignore hace
          WIKI "Trace", true},
    Entry{"athetos_past", Kind::Timeline, {"Athetos's past", "El pasado de Athetos"},
          {"How a rejected scientist became Sudra's destroyer.",
           "Cómo un científico rechazado se convirtió en el destructor de Sudra."},
          {"After the explosion, the original Trace, blind and paralysed, had an epiphany that rewrote physics. Rejected and nicknamed Athetos, he and Hammond crossed the Breach and found Sudra, where a Rebirth Chamber healed him. He travelled 'upstream' toward higher worlds, came back furious that the Sudrans had forgotten their own technology and sealed themselves in, allied with Katrahaska and, by the Rusalki's account, released the pathogen. Crippled in the war that followed, the Rusalki decayed for centuries while he hid in Mar-Uru.",
           "Tras la explosión, el Trace original, ciego y paralizado, tuvo una revelación que reescribió la física. Rechazado y apodado Athetos, cruzó la Brecha con Hammond y encontró Sudra, donde una cámara de renacimiento lo curó. Viajó «río arriba» hacia mundos superiores, volvió furioso porque los sudranos habían olvidado su propia tecnología y se habían encerrado, se alió con Katrahaska y, según los Rusalki, liberó el patógeno. Lisiados en la guerra que siguió, los Rusalki se fueron deteriorando durante siglos mientras él se escondía en Mar-Uru."},
          WIKI "Athetos", true},
    Entry{"story_full", Kind::Timeline, {"The whole story", "La historia completa"},
          {"Everything that happens in the game, including the ending.",
           "Todo lo que ocurre en el juego, final incluido."},
          {"Trace restarts the Power Filter, waking the other Rusalki, and the Repair Drones. In Ukkin-Na the pathogen overwhelms him; he collapses after the Vision and remembers being Athetos. Ophelia heals him and tells him Athetos and the Breach Attractor are above her room. After the Aborted Clone he admits he knows what he is; when he refuses to go on, Elsenova kills him through his nanogates, and Ophelia apologises when he revives. With the Red Coat he climbs Mar-Uru and confronts Athetos, who warns of the Rusalki, 'masters of war', and cannot say more. Once the Attractor falls, Elsenova kills Athetos. Trace then seems to wake on Earth, but the credits suggest a dream built for him, ending with Athetos telling him it is time to wake up.",
           "Trace reactiva el Power Filter, que despierta a las demás Rusalki, y los drones de reparación. En Ukkin-Na el patógeno lo supera; se desploma tras Vision y recuerda haber sido Athetos. Ophelia lo cura y le dice que Athetos y el Breach Attractor están sobre su sala. Tras el Aborted Clone admite que sabe lo que es; cuando se niega a seguir, Elsenova lo mata a través de sus nanogates, y Ophelia se disculpa cuando revive. Con la Red Coat sube a Mar-Uru y se enfrenta a Athetos, que advierte contra los Rusalki, «maestros de la guerra», y no puede decir más. Cuando cae el Attractor, Elsenova mata a Athetos. Trace parece despertar en la Tierra, pero los créditos sugieren un sueño hecho para él, que termina con Athetos diciéndole que es hora de despertar."},  // codespell:ignore mata
          WIKI "Story", true},
    Entry{"theories", Kind::Timeline, {"Who released the plague?", "¿Quién liberó la plaga?"},
          {"A popular reading of the notes that questions the Rusalki.",
           "Una lectura popular de las notas que pone en duda a los Rusalki."},
          {"Trace is lied to through most of the game. Many players think the Rusalki, not Athetos, released the pathogen: the Sudrans had imprisoned them, Katrahaska may have tried to warn Athetos, Ophelia cures the disease easily, and only a vague Sudran notice blames the intruder. Axiom Verge 2 adds more clues about where the plague came from.",
           "A Trace le mienten durante casi todo el juego. Muchos jugadores creen que fueron los Rusalki, y no Athetos, quienes liberaron el patógeno: los sudranos los habían encarcelado, puede que Katrahaska intentara avisar a Athetos, Ophelia cura la enfermedad con facilidad y solo un vago aviso sudrano culpa al intruso. Axiom Verge 2 añade más pistas sobre el origen de la plaga."},  // codespell:ignore creen
          WIKI "Story", true},
    Entry{"endings", Kind::Timeline, {"Endings", "Finales"},
          {"Extra ending scenes depend on how much you completed.",
           "Las escenas finales extra dependen de cuánto hayas completado."},
          {"After the credits, additional scenes appear according to your completion percentage, so finding more items, notes and Secret Worlds shows more of the ending.",
           "Tras los créditos aparecen escenas adicionales según el porcentaje completado, así que encontrar más objetos, notas y mundos secretos muestra más del final."},
          WIKI "Story", false},
};

#undef WIKI

} // namespace

std::span<const Entry> AxiomVergeEntries() {
    return Entries;
}

const Game& AxiomVerge() {
    static constexpr std::array kinds{Kind::All,  Kind::Place,   Kind::Character,
                                      Kind::Boss, Kind::Item,    Kind::Ability,
                                      Kind::Guide, Kind::Timeline};
    static const Game game{
        AxiomVergeProgramId,
        {"Axiom Verge", "Axiom Verge"},
        {"Explore Sudra by topic: areas, bosses, weapons and tools, tips, and the story. The big "
         "revelations stay hidden until you ask for spoilers.",
         "Explora Sudra por temas: zonas, jefes, armas y herramientas, consejos e historia. Las "
         "grandes revelaciones quedan ocultas hasta que pidas spoilers."},
        {"Weapons", "Armas"},
        AxiomVergeEntries,
        kinds,
        nullptr,
        {"Tools and upgrades", "Herramientas y mejoras"},
        {"Story and lore", "Historia y trasfondo"}};
    return game;
}

} // namespace GameCompanion
